INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(351900, 0, 3519, 0, 0, 0, 'Terokkar Forest', 'Terokkar Forest spreads across the heart of Outland, a wood of olemba trees between the marshes of Zangarmarsh and the ash of Shadowmoon Valley. It is thought to take its name from Terokk, the mightiest king the arakkoa remember, and his bird-folk still keep their veils in its groves while his city of Skettis waits in the mountains to the southeast. The draenei once held this land. Tuurem was among the first of their cities to fall to the orcs, and their great necropolis of Auchindoun stands in the south. Two years ago a summoning by the Shadow Council tore Auchindoun open, and the blast scoured the forest around it into the Bone Wastes, where the restless dead now wander. Shattrath City rises in the northwest under the Sha''tar. The Alliance holds the Allerian Stronghold and the Horde holds Stonebreaker Hold, and both contend with arakkoa raiders, fel orcs, the blood elves of Firewing Point and the cultists of the Shadow Council.', 'warcraft.wiki.gg/wiki/Terokkar_Forest (likely named after Terokk; draenei Shattrath, Auchindoun and Tuurem; Bone Wastes; Shattrath in the northwest); quest 9793 description (Tuurem one of the first cities overrun by the orcs); quest 10094 description (two years since the Shadow Council summoning exploded the mausoleum and formed the Bone Wastes); quest 9992 description (olemba trees of the forest); quests 9986, 9998, 9996, 10042 (arakkoa, fel orcs, Firewing blood elves, Shadow Council)'),
(351901, 1, 3519, 1, 0, 0, 'Cenarion Thicket', 'In the forest''s north, the Cenarion Thicket was a quiet outpost of the Cenarion Expedition, gathered around a tall tower among the trees. It is a place of the dead now. Something struck it in a blinding white light, and nearly every druid there died at once. Earthbinder Tavgren, away surveying the Bone Wastes at the time, came back to find only one other survivor: Warden Treelos, who still wanders the tower in shifting shapes, babbling of light and silence and of the eyes of Naphthal''ar atop the tower, which will not stop staring. The thicket''s teromoths survived as well, but they are vicious now, infused with a residue of pure mana that leaves them agitated and quick to attack.', 'quest 9957, 9960, 9961 reward text (druids slain, two survivors, one insane); quest 9971 description (Tavgren away surveying the Bone Wastes); quest 9968 reward text (vicious teromoths infused with pure mana); quest 9951 description (Naphthal''ar atop the tower); creature_text 18424 (Treelos: blinding white light, then silence; can''t control form; it sees all); zone_areas: Fallen Druid, Vicious Teromoth, Warden Treelos, Naphthal''ar in area 3674'),
(351902, 1, 3519, 2, 0, 0, 'Tuurem', 'Tuurem was a draenei town in the northern reaches of the forest, home to Vindicator Idaar before it became one of the first of his people''s cities overrun by the orcs. Its ruins have not been left in peace. Broken of the Wrekt and other scavengers pick through the rubble, and there are rumors of artifact hunters robbing it of relics. Some of its old vessels still brim with raw magical energy, which the high elf Ros''eleth of the Allerian Stronghold hopes will help her scattered people resist the lure of demonic magic. Lately the town has served darker ends: crates of exotic engineering parts bought in Shattrath were delivered here, bound for the blood elves of Firewing Point.', 'quest 9793 description and reward text (Idaar''s former home, one of the first cities overrun; ruins in the northern reaches); quest 10104 description (crazed Broken, artifact hunters); quest 10028 description (vessels of raw magical energy; quel''dorei resisting demonic magic); quest 9990 description and reward text (engineering parts delivered to Tuurem; last box bound for Firewing Point); warcraft.wiki.gg/wiki/Tuurem; zone_areas: Wrekt Seer, Wrekt Warrior, Tuurem Scavenger, Tuurem Hunter, Firewing Courier in area 3675'),
(351903, 1, 3519, 3, 0, 0, 'Veil Reskk and Veil Shienor', 'Veil Reskk and Veil Shienor are arakkoa colonies in the northern woods, home to Shienor talonites, sorcerers and wing guards. Like every veil of the forest they answer to Skettis. Their warriors ambush hunters and couriers on the roads, strike at the garrisons by night, and escape through summoning circles before a warband can catch them. Each colony guards an Eye of Skettis, an orb enchanted by black art through which Terokk is said to watch over his colonies, and redeemed arakkoa in Shattrath long to look through them. The leaders of the two veils, Ashkaz of Reskk and Ayit of Shienor, are marked for death by the Alliance and the Horde alike.', 'quest 10868, 10869 descriptions (night raids, summoning circles, Reskk and Shienor north); quest 9986, 9987 descriptions (Ashkaz in Reskk, Ayit in Shienor); quest 10847 description (Eyes of Skettis in Reskk and Shienor); zone_areas: Shienor Talonite, Sorcerer, Wing Guard, Ashkaz, Ayit, Eye of Veil Reskk/Shienor'),
(351904, 1, 3519, 4, 0, 0, 'Veil Skith', 'Veil Skith hides in a secluded grove just south of Shattrath, a colony of Skithian windrippers and dreadhawks led by Urdak. The Skithians are bold thieves who made off with a great shipment of exotic goods belonging to the ethereal Wind Trader Lathrai, and they carried children from a refugee caravan back to their cages here. Their altar, the Darkstone of Terokk, was raised for the colony''s worship of Skettis, and Kirrik the Awakened hoped a rod blessed by the naaru A''dal could purify it and redeem the Skithians. When the rod was used, the Darkstone exploded, and Kirrik, who felt the blast in his heart, judged that those who would not turn to the Light could not be saved.', 'quest 10839 description and reward text (secluded grove south of Shattrath; Darkstone; rod blessed by A''dal; explosion; those not given to the Light must be destroyed); quest 10112 description (Skithians stole Lathrai''s goods; Veil Skith south of Shattrath); quest 10852 description (children taken northwest by bird men); quest 9986 description (Urdak in Veil Skith); zone_areas: Captive Child x14, Veil Skith Cage, Skithian Windripper, Dreadhawk, Urdak in area 3677'),
(351905, 1, 3519, 5, 0, 0, 'Stonebreaker Hold', 'Stonebreaker Hold is the Horde''s town in the middle of the forest, an orc hold of watchtowers commanded by Rokag. Its people are a mixed lot. The blood elf Advisor Faila wonders what misstep earned her this posting, the troll Tooki warns that the forest holds worse juju than the Alliance, and Kurgatok bickers with his ill-mannered imp. Mawg Grimshot, who lost an eye to the bonelasher king, posts bounties on the beasts, and the trader Rakoria presses olemba seeds into oil to sell along the roads. Messengers run the dangerous road north to Swamprat Post in Zangarmarsh. For Malukaz the hold is something more: a return to a land his people once called home.', 'npc_text 9522 (Faila: misstep to be assigned here); npc_text 9392 (Tooki: bad juju); quest 10027 texts (Kurgatok and the imp Keb''ezil); quest 10036 description and npc_text 9485 (Mawg lost an eye to Torgos); quest 9993, 10201, creature_text 18385 (Rakoria''s olemba oil); quest 9796, 10105 (Mokasa''s messengers, runners lost to Alliance outriders, Swamprat Post); npc_text 9488 (Rokag runs the hold''s defenses); quest 10018 description (orc clans once called Terokkar home); warcraft.wiki.gg/wiki/Stonebreaker_Hold (watch towers, Rokag leader)'),
(351906, 1, 3519, 6, 0, 0, 'Allerian Stronghold', 'The Allerian Stronghold is the Alliance''s foothold in eastern Terokkar. It bears the name of Alleria Windrunner, and many of its defenders are high elves who stayed in Outland: rangers walk its walls, and the seamstress Ros''eleth admits she once hoped to meet the town''s namesake. Captain Auric Sunchaser commands, while Lieutenant Gravelhammer brings him one crisis after another, a burning sentry tower, a missing merchant, mercenaries from Honor Hold stirring up trouble. Trouble rings the garrison on every side. Arakkoa raid its roads, fel orcs dig in at the ruins to the east, and to the south lie the Bone Wastes, where at least one of its defenders flatly refuses to go, whatever the bounty.', 'warcraft.wiki.gg/wiki/Allerian_Stronghold (named after Alleria Windrunner; high elves under Auric Sunchaser); npc_text 9492 (Ros''eleth hoped to meet the town''s namesake); creature_text 18713, 18745 (Gravelhammer''s reports, Sunchaser''s replies); creature_text 18999 (defender refuses to go into the Bone Wastes); quest 9998 description (fel orcs at the ruins to the east); zone_areas: High Elf Ranger x5, Allerian Defender in area 3684'),
(351907, 1, 3519, 7, 0, 0, 'Firewing Point', 'Firewing Point is a blood elf citadel in the northeast of the forest, its spire rising over a walled courtyard. Its masters serve Kael''thas, and through him Illidan, and its warlocks and bloodwarders guard a terrible project: mana bombs, weapons of pure mana able to wipe out a whole town. The overseer Sharth Voldoun keeps to the top of the highest spire and holds the final codes himself. A Cenarion envoy, Isla Starmane, came here on a diplomatic mission and found herself locked in a cage. On the river''s banks to the south and southwest, the Alliance keeps the Allerian Post and the Horde keeps Stonebreaker Camp, small forward posts watching the spire.', 'quest 9996, 9997 descriptions (working for Kael''thas and Illidan); quest 10446 description (second mana bomb in the courtyard; Sharth Voldoun atop the highest spire holds the final code); quest 10005 reward text (mana bomb that can take out whole towns); quest 10051 description (Isla Starmane, Cenarion Expedition diplomatic mission); quest 10444, 10448 descriptions (Allerian Post south of Firewing Point, Stonebreaker Camp southwest, on the river); warcraft.wiki.gg/wiki/Firewing_Point (northeastern Terokkar)'),
(351908, 1, 3519, 8, 0, 0, 'Bonechewer Ruins', 'East of the Allerian Stronghold lie the Bonechewer Ruins, where fel orcs of the Bonechewer have lately moved in and set to rebuilding. The work never stops: warped peons repair the buildings and raise fortifications day and night, while devastators and backbreakers stand guard and messengers watch the roads. Their arrival troubled both garrisons, for the Horde at Thrallmar had believed the fel orcs safely contained around Hellfire Citadel. The answer lay in plans found in the camp, written in a hand far too delicate for any orc. The Bonechewer take their orders from the blood elves of Firewing Point, who sent a liaison back and forth between the camps, and they were told to keep the garrisons occupied.', 'quest 9998 description (fel orcs at the ruins to the east, construction day and night); quest 10000 description (Thrallmar thought them contained in the Hellfire Citadel area); quest 10012, 10013 (Fel Orc Plans, writing too delicate, ordered to keep us occupied); quest 10002 description (blood elf liaison); zone_areas: Warped Peon, Bonechewer Devastator, Backbreaker, Messenger, Lisaile Fireweaver, Fel Orc Plans in area 3685'),
(351909, 1, 3519, 9, 0, 0, 'Grangol''var Village', 'Grangol''var Village is a ruined settlement west of Stonebreaker Hold, on the northern fringe of the Bone Wastes. A shadowy band has moved into its broken buildings: robed summoners and executioners, a laborer who grumbles about his pay, and an advisor who threatens to have strangers beaten. They are the Shadow Council, led by Shadowmaster Grieve, who offers any who cross him a grave in the labyrinth of Auchindoun or a place as a sacrifice to Murmur. Their gossip betrays them, for the cultists whisper that the council has lost all control of Murmur in the Shadow Labyrinth. Scouts from both garrisons keep watch on the village entrances, though their reports went unanswered for more than a week.', 'quest 10038, 10039 descriptions and reward text (west past Stonebreaker Hold, skirting the north of the Bone Wastes; reports over a week old); npc_text 9497, 9505 (laborer, advisor); npc_text 9524 (Grieve: labyrinth of Auchindoun, sacrifice to Murmur); npc_text 9523 (lost total control of Murmur); warcraft.wiki.gg/wiki/Grangol''var_Village (orc ruin, Shadow Council under Grieve); warcraft.wiki.gg/wiki/Grangol''var_Village (Shadow Council warlocks under Grieve)'),
(351910, 1, 3519, 10, 0, 0, 'Bleeding Hollow Ruins', 'On the western border with Nagrand lie the Bleeding Hollow Ruins, until lately a village of Bleeding Hollow orcs. Boulderfist ogres fell on it in a cowardly night attack, and the survivor Jorin Deadeye fled to Garadar to beg for help. The ogres hold the village still. Their fat leader, Unkor the Ruthless, makes his lesser followers dance for him while he waits for something none of them will name, and Kilrath, a scout sent from Garadar, hides at the edge of the ruins, watching. To the Mag''har it is also one of the old villages of their ancestors. What Kilrath and his helpers learned from Unkor is a tale told in Garadar.', 'quest 9888 description and reward text (night attack, Kilrath hides on the border, the fat one makes the lesser ones dance); quest 9889 description (he says he is waiting for something); nagrand.json 351839 and 351834 (Bleeding Hollow among the villages of the ancestors; Lantresor''s Gambit tells the Kilrath chain); zone_areas: Boulderfist Invader, Unkor the Ruthless in area 3719; Kilrath at 3519 nearby'),
(351911, 1, 3519, 11, 0, 0, 'Refugee Caravan', 'On the road south of Shattrath, at the northern edge of the Bone Wastes, a caravan of refugees from the Lower City sits stalled beside its wagons. Broken and humans, orcs and redeemed arakkoa traveled together until Shadow Council cultists struck in the night, and now their guards wait for the help called from Shattrath. Each traveler has a reason to be here. Kirrik the Awakened seeks his people in the colonies; High Priest Orglum came to cleanse the troubled spirits of the wastes; Soolaveen would ease the pain of the restless dead; Lakotae would heal the blasted land. A boy named Ethan simply wants his friends back, carried off by the bird men in the night.', 'quest 10849 description (road south of Shattrath to the Bone Wastes; Kirrik in the colonies); quest 10878 description (Shadow Council cabal attack, scouts sent to Shattrath); quest 10880 reward text (Mekeda lives among outcasts and refugees in the Lower City); npc_text 10680, 9477, 10677 (Orglum, Soolaveen, Lakotae); quest 10852 description (Ethan''s missing friends); zone_areas: Human, Orc, Shattrath and Skettis Refugees, Redeemed Avian, Caravan Defender in area 3887'),
(351912, 1, 3519, 12, 0, 0, 'The Bone Wastes', 'The Bone Wastes are a scar of dust and bleached bone at the heart of the forest, left where the blast from Auchindoun blew the land around the necropolis bare. The dead do not rest here. Lost spirits and broken skeletons, draenei corrupted by the explosion, wander in blind torment, and the bones of the fallen lie scattered for any who would carry them to a proper grave. Plague-carrying bonelashers, scorpids and burrowing bone worms prowl the sand, wood mites gnaw at the trees along its edges, and ethereal plunderers and Shadow Council cabalists pick over its tombs. Five spirit towers stand in the wastes, and by ancient custom the living come to pay their respects there at certain hours.', 'quest 10896 description (foul magic from Auchindoun blasted the land into wastes; wood mites); quest 10030, 10031 descriptions (bones of the dead from the explosion; corrupted spirits); quest 10033 description (bonelashers carry plague); quest 10929 (bone worms); quest 11505 description (ancient custom, respects at spirit towers at specific times); warcraft.wiki.gg/wiki/Spirit_Towers (five towers); zone_areas: Lost Spirit, Broken Skeleton, Scorpid Bonecrawler, Ethereal Plunderer, Cabal Skirmisher in area 3697'),
(351913, 1, 3519, 13, 0, 0, 'The Shadow Tomb and the Tomb of Lights', 'Two tombs lie near the refugee caravan, and neither rests easy. The Shadow Tomb, to the west, has been taken by Shadow Council cabalists fleeing Auchindoun, who use it to store the powerful artifacts they carried out of the necropolis, among them the relics of the patriarchs Arunen, K''alen and Atalor. To the east, buried under charred sand, lies the Tomb of Lights, a lost resting place of the dead. Ethereals plunder its bodies for keepsakes laid beside them centuries ago, and the Shadow Council has corrupted it so deeply that its draenei dead have risen as vengeful spirits, angry and confused, with a burning hatred for the living.', 'quest 10881 description (Shadow Tomb west of the caravan; artifacts of Arunen, K''alen, Atalor); quest 10840 description (Tomb of Lights to the east under charred sand; ethereals plunder keepsakes); quest 10842 description (corrupted by the Shadow Council; vengeful draenei); zone_areas: Cabal in 3888; Ethereal Nethermancer, Plunderer, Vengeful Draenei in 3890'),
(351914, 1, 3519, 14, 0, 0, 'Veil Rhaze', 'Veil Rhaze was a particularly wicked colony of Skettis on the western edge of the Bone Wastes, west of the Shadow Tomb. The blast that tore Auchindoun apart destroyed it, but did not end it: the malevolent spirits of its people still haunt the ruins as deathtalons, screeching spirits and spirit ravens, bound to Terokk''s will. Overhead circles Torgos, king of the bonelashers, who took Mawg Grimshot''s eye while he hunted here. Torgos keeps away from an old arakkoan scarecrow called Torgos''s Bane, and hunters say only the carcass of his mate Trachela, laid at its foot, will draw him down. She nests with the other bonelashers at Carrion Hill in the north of the wastes.', 'quest 10848 description (wicked colony destroyed by the Auchindoun disaster; Terokk''s influence in the spirits; west of the Shadow Tomb); quest 10035, 10036 descriptions (Torgos circles over Veil Rhaze, Torgos''s Bane scarecrow, Trachela at Carrion Hill, Mawg''s eye); gameobject 184842 Torgos''s Bane; zone_areas: Deathtalon Spirit, Screeching Spirit, Spirit Raven, Torgos in area 3889; Trachela in 3891'),
(351915, 1, 3519, 15, 0, 0, 'Veil Lithic', 'Veil Lithic lies in the southwest of the forest, a colony of Lithic oracles and talonguards loyal to Skettis. Its sorcerers practice an especially cruel art. They wrap unhatched eggs in a shadowy curse, so that the hatchlings which emerge are born as mindless servants of Terokk. Kirrik the Awakened of the refugee caravan asks those who would help to break the cursed eggs early, redeeming the hatchlings that can still be saved and putting down the ones the curse has already claimed. Even Kirrik admits it is grim work to meddle with another''s hatchlings, but he holds that leaving the evil to brew would be bleaker still.', 'quest 10861 description and reward text (colony to the southwest; cursed eggs; redeem and slay hatchlings; grim work); zone_areas: Lithic Oracle, Lithic Talonguard, Cursed Egg in area 3686'),
(351916, 1, 3519, 16, 0, 0, 'Auchindoun and the Ring of Observance', 'Auchindoun was the great necropolis of the draenei, born from a first tomb where Prophet Velen laid the remains of a fallen naaru, and the Auchenai death priests tended its dead for some five hundred years. Two years ago a Shadow Council summoning tore it open. Its four wings now hold rival powers: ethereals plunder the Mana-Tombs, the maddened Auchenai keep the Crypts, the Sethekk arakkoa hold their halls, and the Shadow Council struggles to contain Murmur, the being it called, in the Shadow Labyrinth. At its center lies the Ring of Observance, where draenei spirits drift among the stones, Lower City agents hold the door of the labyrinth, and the outcast death priest Ramdor grumbles over the bones.', 'quest 10167 description and reward text (the first tomb from which the mausoleum was born; Velen laid D''ore''s remains there); quest 10228 description (caring for the dead these last 500 odd years); quest 10094, 10095 (Shadow Council summoning two years ago; Murmur); quest 10165 (Shaffar in the Mana-Tombs); quest 10227 reward text (the Auchenai all mad); quest 10097 (Sethekk Halls); quest 10177 and npc_text 9833 (Lower City at the Shadow Labyrinth entrance); quest 10950 (Ring of Observance in the middle of Auchindoun); zone_areas: Ancient Draenei Spirit, Ramdor, Lower City Operative in 3688/3893'),
(351917, 1, 3519, 17, 0, 0, 'The Shadow Stair', 'The Shadow Stair climbs to Auchindoun''s northern entrance and the sealed doors of the Mana-Tombs, inside which the ethereal Nexus-Prince Shaffar plunders the crypt for all it is worth. Outside, a rival Consortium camp waits under Nexus-Prince Haramad, who greets visitors by asking those sent to kill him to take a number and wait their turn. His Captain Kaftiz swears that Shaffar''s wards will break any minute now, while his artificers look for another way in and a shady dealer sells only to friends of the Consortium. They share the stair uneasily with Shadow Council cabalists, whose skirmishers and spell-weavers gather on its steps.', 'quest 10165 description (Shaffar keeps the Consortium out while pillaging the crypt); npc_text 9903 (Haramad: take a number); npc_text 9897 (Kaftiz: ward, open any minute); quest 10216 description (Morphalius''s plan for another way in); npc_text 9895, 9896 (Slim); quest 10878 description (cabal at Auchindoun''s northern entrance); zone_areas: Consortium NPCs, Cabal Skirmisher, Spell-weaver, Initiate in area 3956'),
(351918, 1, 3519, 18, 0, 0, 'Sha''tari Base Camp', 'Southwest of Auchindoun, the Sha''tar have pitched a base camp in the wastes, where great elekk stand among Commander Ra''vaj''s vindicators. Their war is with the Auchenai, and the battle on the Auchenai Grounds east of the camp has raged for days, every fallen soldier on either side snatched away and its soul lifted for some dark rite. The camp is beset on other fronts too: spiders from Netherweb Ridge raided it by night and carried off its people, and Oakun broods over a way to destroy the cursed thing that flies over the wastes. An Explorers'' League dig under the hapless Chief Archaeologist Letoll shares the camp, hunting bone worms with a drum unearthed at their dig.', 'quest 10913, 10914 descriptions (battle east of the outpost; souls taken from the fallen); quest 10873 description (spiders of Netherweb Ridge raided the outpost); quest 10877 description (Oakun and Teribus); quest 10922 reward text and creature_text 22458 (Letoll''s first discovery, the drum); quest 10929 (Explorers'' League, the fumper); zone_areas: Great Elite Elekk, Sha''tar Vindicator, Ra''vaj, Oakun, Letoll, Dwarfowitz in 3958; Slain Auchenai Warrior in 3894; posarea: base camp at -3746,5409, southwest of the Ring of Observance; gameobject 184458 Meeting Stone at the Ring of Observance (-3329,4936)'),
(351919, 1, 3519, 19, 0, 0, 'Writhing Mound', 'Northeast of Auchindoun, beyond its walls, rises the Writhing Mound, a place where necromancers gather. Auchenai death-speakers and doomsayers work their rites there among rats and restless bones, and the doom skulls they carry are laced with powerful necromantic enchantments. Pale death-spirits linger about the mound. At its heart lies a summoning circle, and the Sha''tar have learned that skulls enough, joined with a relic of true evil, can command Teribus the Cursed to come down from the skies and face whoever called it.', 'quest 10923 description (to the northeast beyond Auchindoun; necromancers; doom skulls; summoning circle; Teribus); zone_areas: Auchenai Doomsayer, Death-Speaker, Death-Spirit, Restless Bones in area 3892'),
(351920, 1, 3519, 20, 0, 0, 'Netherweb Ridge', 'On the southeastern edge of the Bone Wastes rises Netherweb Ridge, the lair of the dreadfang widows. The spiders hunt by night, poisoning their victims, wrapping them in webs and carrying them off to the ridge, where cocooned prisoners hang among the rocks. They struck the Sha''tari Base Camp this way, and the warriors who chased them into the dark did not return; Vindicator Haylen and his last companions lie poisoned just west of the ridge. Deep within lurks the brood-mother of them all, the great Terokkarantula, and while she lives the widows will keep on spawning.', 'quest 10873 description (Netherweb Ridge on the southeastern edge of the Bone Wastes; poisoned, webbed and carried away); quest 10920, 10921 descriptions (Haylen west of the ridge; Terokkarantula the brood-mother); zone_areas: Netherweb Victim, Dreadfang Widow, Terokkarantula in area 3885'),
(351921, 1, 3519, 21, 0, 0, 'Veil Shalas', 'At the foot of the cliffs beneath Skettis lies Veil Shalas, the most formidable of Terokk''s colonies, home to Shalassi oracles and talonguards. Through Shalas the forward sages of Skettis wage their war on the Light, and four magical signal fires, burning emerald, violet, bloodstone and sapphire, carry word between the colony and its master. One of the redeemed, Skywing, came here hoping to sway the Shalassi toward the Light. They answered with the curse of Luanga the Imprisoner, one of Terokk''s most feared agents, which left him a small fluttering bird until a stranger followed him back to Veil Shalas, slew Luanga and saw the curse broken.', 'quest 10874 description (base of Skettis; most formidable colony; forward sages; signal fires); gameobjects 185216-185219 (Emerald, Violet, Bloodstone, Sapphire Signal Fire); quest 10898 description and reward text (Skywing cursed by Luanga, one of Terokk''s most feared agents); creature_text 22424 (Skywing leads into the tree; free at last from the curse); zone_areas: Shalassi Oracle, Talonguard in area 3678; creature_template_model 22424 display 20998 (Parrot model); smart_scripts 22424, 18533 (Luanga summoned, death breaks the curse)'),
(351922, 1, 3519, 22, 0, 0, 'Blackwind Landing', 'Blackwind Landing is the camp of the Sha''tari Skyguard in the northern Skethyl Mountains, just outside Skettis, where nether rays rest between sorties. The Skyguard is Shattrath''s air wing, and after a sharp rise in arakkoa activity was followed by attacks on the city, it posted riders here to watch Skettis from above. The war is hard on them. Dozens of sorties fly each day, feed for the rays runs short, and scouts are knocked from the sky by monstrous kaliri. Sky Commander Adaris lies wounded in camp under the care of Severin, while Sky Sergeant Doryn drills new recruits. Nearby, in a cage, sits an arakkoa prisoner named Hazzik, cursing his captors.', 'quest 11098 description (increase in arakkoa activity, attacks on Shattrath, forces stationed outside the city); quest 11096 description (Skyguard sworn to protect Shattrath); quest 11093 description (dozens of sorties, feed shortages); quest 11085 description (scout knocked from his nether ray); quest 11004 description (Adaris injured; Severin); npc_text 10819, 10903 (Doryn; Hazzik''s curses); warcraft.wiki.gg/wiki/Sha''tari_Skyguard (air wing of the Sha''tar; Blackwind Landing in the northern Skethyl Mountains); zone_areas: Arakkoa Cage, Skyguard Nether Ray in area 3973'),
(351923, 1, 3519, 23, 0, 0, 'Skettis', 'High in the Skethyl Mountains of southeastern Terokkar lies Skettis, the hidden city of the arakkoa, its dwellings rising around the waters of Blackwind Lake. From here Terokk''s power reaches every veil in the forest. Its quarters of Veil Harr''ik, Veil Ala''rak and Upper and Lower Veil Shil''ak are guarded by wing guards, windwalkers and soulcallers, and by the strange time-lost arakkoa. Monstrous kaliri, bred as war birds, nest atop the dwellings. On the island of Terokk''s Rest at the heart of the city, an old and nearly blind scribe named Sahaak keeps his books, and there, the talonpriests believe, their ancient king will one day return.', 'warcraft.wiki.gg/wiki/Skettis (hidden capital of the arakkoa in Blackwind Valley; Terokk''s Rest the summoning site); quest 11008 description (gargantuan kaliri bred atop the dwellings); quest 11029 description (Sahaak at Terokk''s Rest, old and nearly blind); quest 11028 description (almanac presages Terokk''s return); zone_areas: Skettis Wing Guard, Windwalker, Soulcaller, Time-Lost Skettis arakkoa across 3974-3978'),
(351924, 2, 3519, 1, 0, 0, 'Earthbinder Tavgren', 'Earthbinder Tavgren of the Cenarion Expedition was away on a survey of the Bone Wastes when death came to the Cenarion Thicket. He returned to find his fellow druids slain and only Warden Treelos alive, his mind broken. Refusing to leave, Tavgren camped outside the thicket and set about learning what had happened, studying mana-soaked teromoths, a dead Broken found with a strange object, and the trail of a merchant''s boxes. When the truth came back to him, a blood elf bomb of pure mana, he could only ask why anyone would turn such a weapon on a place of peace and repose, and hope that Treelos''s mind might heal in time.', 'quest 9971 description (away surveying the Bone Wastes); quest 9957 reward text (druids slain, one other survivor insane); quest 9968, 9971, 9978 (his investigation); quest 10005 reward text (mana bomb; place of peace and repose; Treelos may heal in time); npc_text 9391'),
(351925, 2, 3519, 2, 1, 0, 'Captain Auric Sunchaser', 'Captain Auric Sunchaser is the high elf who commands the Allerian Stronghold and the high elves who chose to stay there. His days are a parade of bad news delivered by his aide, Lieutenant Gravelhammer: a fire in the sentry tower, a missing merchant, a Cenarion druid held captive at Firewing Point. He meets each report with weary questions about what else could possibly go wrong, yet every one ends with an order to see it handled, to call in the scouts or to notify anyone who can help. It is to Sunchaser that the Cenarion envoy Isla Starmane brings her full account of Firewing Point after her escape, and he thanks her rescuers on behalf of the stronghold.', 'warcraft.wiki.gg/wiki/Auric_Sunchaser (high elf captain at Allerian Stronghold); warcraft.wiki.gg/wiki/Allerian_Stronghold (high elves stayed under him); creature_text 18713, 18745 (Gravelhammer''s reports and Sunchaser''s replies); quest 10051 reward text (Isla''s rundown; indebted on behalf of the stronghold)'),
(351926, 2, 3519, 3, 2, 0, 'Rokag', 'Rokag commands Stonebreaker Hold, and he has little patience for anything that is not defense or supply. When Malukaz chatters about the forest''s history, Rokag grants that the work matters but points out that someone must see to the defenses and logistics while the present''s problems remain unsettled. His answer to the arakkoa is blunt: kill their leaders in Reskk, Shienor and Skith, and when he hears that some arakkoa in Shattrath claim friendship with the Horde, send a messenger to demand their surrender. He keeps the shadowstalker Kaide watching the fel orcs in the ruins to the east, and is disturbed when their plans reveal that they are colluding with the blood elves.', 'npc_text 9488 (Malukaz chatters; defenses and logistics); quest 9987 description (kill Ashkaz, Ayit and Urdak); quest 10862 description (demand Rilak''s surrender); quest 10000 description (Rokag dispatched Kaide); quest 10013 reward text (colluding with the blood elves; disturbing news)'),
(351927, 2, 3519, 4, 0, 0, 'Theloria Shadecloak', 'Theloria Shadecloak is a high elf who watches from the Allerian Post, a small watch north of the Bonechewer Ruins. She is an exile. When the Dark Portal opened she learned what had become of her people, and seeing the Farstriders throw in their lot with Kael''thas ended the homecoming she had dreamed of; her exile spared her their downfall, she says, but this forest is now the only home she has left. It was Theloria who shadowed a blood elf woman from the fel orc camp north toward Firewing Point, and she means to stall any reinforcements the fel orcs try to bring to their ruins.', 'npc_text 9490 (exile; Farstriders with Kael''thas; homecoming will never happen; forest the only home); quest 9998 description and reward text (Allerian Post north of the Bonechewer Ruins; the high elf nods); quest 10002 description (shadowed the blood elf woman to Firewing Point); quest 10007 description (stall reinforcements)'),
(351928, 2, 3519, 5, 0, 0, 'Kirrik the Awakened', 'Kirrik the Awakened is an arakkoa who saw through Terokk. Where others in Skettis took him for a prophet, Kirrik named him a charlatan whose only true prophecy was the doom he brought about himself, and it was Kirrik who bravely led the exiles out of Skettis on their pilgrimage to Shattrath, where they learned of the Light through A''dal. Kirrik did not stay behind the city''s walls. He went back out into the colonies in search of others who might be saved, and he now waits with the refugee caravan in the Bone Wastes, guiding strangers against the veils. Those who will not turn to the Light, he has come to believe, are mere servants of evil.', 'quest 10849 description (charlatan, not a prophet; led us from Skettis; pilgrimage to Shattrath; traveled to the colonies); quest 10847 description (learned of the Light through A''dal); quest 10839 reward text (those not given over to the Light are servants of evil)'),
(351929, 2, 3519, 6, 0, 0, 'Ramdor the Mad', 'Ramdor the Mad stands on the bone pile outside the Auchenai Crypts, scowling at spirits only he and a child can see. He was once a death priest of the Auchenai, a title he now finds unsavory. When Exarch Maladaar turned the priory to experiments in necromancy, Ramdor held that the dead they had cared for some five hundred years should simply be left alone, and he was cast out for his beliefs. He calls the Auchenai insane to the last, yet the dead will not leave him in peace. He is gruff and a self-confessed liar, but he sees that the bones of the ancestors are properly buried.', 'quest 10227 description and reward text (death priest; unsavory title; the Auchenai mad; excommunicated); quest 10228 description (dead cared for 500 odd years should be left alone; Maladaar''s necromancy); npc_text 9914 (lambs, lemmings); quest 10253 reward text (I lied to get this book); quest 10030 reward text (proper burial for the bones)'),
(351930, 2, 3519, 7, 0, 0, 'Isfar', 'Isfar is an arakkoa who once followed the Sethekk. When Auchindoun exploded, the Sethekk took it as an omen of their master''s arrival and marched out of Skettis with great fanfare to face their god in the temple ruins, and Isfar went with them, for his older brother Syth was one of their leaders. In time he came to doubt Syth and his ally Ikiss, and Syth had him cast out of the halls while keeping their sister Lakka prisoner. Isfar found safety in Shattrath but could not stay. He has crept back to the entrance of the Sethekk Halls, hoping to free Lakka and to restore the stolen relics of Terokk to his people.', 'quest 10097 description (Sethekk departure, Syth, Ikiss, Lakka); quest 10098 description (relics of Terokk borne away by the Sethekk); npc_text 9634 (older brother; Shattrath; true home in Skettis); quest 10180 description (left the safety of Shattrath)'),
(351931, 2, 3519, 8, 0, 0, 'Sky Commander Adaris', 'Sky Commander Adaris leads the Sha''tari Skyguard at Blackwind Landing, and he leads it from his sickbed. Badly wounded in a Skettis incursion, he drifts in and out of consciousness, muttering that unseen arakkoa are all around, watching and waiting. His healer Severin took it for fevered delirium when Adaris demanded an elixir of arakkoa shadow dust to see into a world of shadows, but the commander was right, for the talonpriests at the head of Skettis had hidden there all along. Adaris is stubborn and slow to trust strange plans, fearing a mutiny among his weary riders, yet once persuaded he commits them fully.', 'quest 11004 description (seriously injured in a Skettis incursion; feverish delirium; world of shadows); quest 11005 description (talonpriests, the chain of command); npc_text 11089 and creature_text 23038 (unseen arakkoa); quest 11073 description (would have faced a mutiny; will command my men to back you up)'),
(351932, 2, 3519, 9, 0, 0, 'David Wayne', 'David Wayne is a human blacksmith who lives alone at Wayne''s Refuge, a scrap of land just east of Firewing Point. He came to Draenor with the Sons of Lothar, and though he left Honor Hold behind, he says the Sons never quite leave a man. He cannot fully explain why he went. He only feels that he is not meant to be at Honor Hold right now, and that he may be meant to be part of something larger. His skill at the forge is known well enough that the smiths of Shadowmoon Valley, Alliance and Horde alike, send him work too difficult for their own anvils.', 'npc_text 10500 (Sons of Lothar; not meant to be at Honor Hold; part of something larger); warcraft.wiki.gg/wiki/David_Wayne (Wayne''s Refuge just east of Firewing Point); quest 10662, 10663 (Shadowmoon smiths send their work to him); shadowmoon.json 352042 (Illidari-Bane Blade)'),
(351933, 2, 3519, 10, 0, 0, 'Teribus the Cursed', 'Teribus the Cursed is a creature that flies over the Bone Wastes, and Oakun of the Sha''tar means to see it brought down. The key, Oakun believes, is a Dread Relic. Long ago a caravan went to Auchindoun to take it from the ancient tombs beneath the necropolis, and though they fled with it, the relic was their undoing, for it summons evil to whoever touches it; their wagons still lie wrecked to the east. Carried to the summoning circle of the Writhing Mound and joined with doom skulls taken from the Auchenai necromancers there, the relic can force Teribus to come down and fight, and so purge a great evil from the skies of Terokkar.', 'quest 10877 description (Dread Relic; caravan destroyed to the east; summons evil when touched; Teribus flies over the Bone Wastes); quest 10923 description and reward text (Writhing Mound, doom skulls, summoning circle; a great evil cleansed from Terokkar); zone_areas: Derelict Caravan 3886 with Vengeful Husk and Accursed Apparition'),
(351934, 2, 3519, 11, 0, 0, 'Terokk', 'Terokk is the mightiest and most terrible king in arakkoa history, a hero whose deeds and splendid plumage are still described to every hatchling. He dwelt among his people for hundreds of years and then vanished, leaving behind only his mask, his spear and his writings, relics the Sethekk later bore away from Skettis. Not all remember him fondly. To the exiles of Shattrath he was a charlatan, and the lowest caste of his city would have been sacrificed to the dark powers his talonpriests worshipped. The talonpriests have not forgotten him. Their almanac foretells his return, and when called back too early he rages that the stars are not aligned and boasts that he cannot be killed.', 'quest 10098 description (hero honored by hatchlings, beautiful plumage, hundreds of years, mask, spear, writings); quest 11028 description (most powerful and terrible Skettis king; almanac presages his return); quest 10849 description (charlatan); quest 11056 description (lowest caste sacrificed under his rule); creature_text 21838 (stars not yet aligned; I am immortal); warcraft.wiki.gg/wiki/Terokk (BC section only)'),
(351935, 3, 3519, 1, 0, 0, 'The Mana Bomb', 'When word stopped coming from the Cenarion Thicket, the Cenarion Refuge, Stonebreaker Hold and the Allerian Stronghold each sent someone to look. They found Earthbinder Tavgren alone outside a thicket of the dead. Its teromoths were soaked in pure mana, and beside a dead Broken lay a strange object. The Broken merchant Empoor, once beaten into talking, admitted only that he carried boxes for an ethereal in Shattrath. Wind Trader Lathrai''s memory improved when his stolen goods were won back from Veil Skith: he had sold exotic engineering parts, delivered to Tuurem. A last box, found there as a blood elf prepared to carry it to Firewing Point, held bomb parts. From forward posts by the river the garrisons struck at Firewing Point, where Sharth Voldoun boasted to his master that the prototype tested on the thicket had worked and a second bomb would soon fall on the nearby pests. Taking his final code, the attackers set that bomb off in Firewing''s own courtyard, and both garrisons celebrated their deliverance.', 'quests 9957, 9960, 9961, 9968, 9971, 9978, 9979, 10112, 9990, 9994, 9995, 10444, 10448, 9996, 9997, 10446, 10447, 10005, 10006; npc_text 9406 (Empoor beaten to within an inch of his life); creature_text 18554 (Sharth Voldoun: prototype at the Cenarion Thicket a complete success; bomb on those nearby pests); creature_text 18447, 18459, 21400 (celebrations)'),
(351936, 3, 3519, 2, 0, 0, 'The Fel Orcs of the Bonechewer Ruins', 'Fel orcs had come to the ruins east of the garrisons and were building day and night. For the Alliance, Bertelm sent volunteers against their peons and on to Theloria Shadecloak at the Allerian Post; for the Horde, Kurgatok sent them against the same peons and on to Shadowstalker Kaide, watching from the trees. Thrallmar had believed the fel orcs safely contained around Hellfire Citadel. Both watchers had seen a blood elf woman come and go from the fel orc camp, giving orders, then return north to Firewing Point. The liaison, Lisaile Fireweaver, was hunted down, and plans found in the camp, written in a hand too delicate for any orc, showed that the Bonechewer were there to serve the blood elves and to keep the garrisons occupied. Thinning their ranks bought time. Kaide asked one thing more of his Horde helpers: that word of the trouble never reach Thrallmar, lest the hold receive a great deal of unwanted company. Some stories, he said, are best left where they happened.', 'quest 9998, 10000 descriptions (fel orcs at the ruins; Thrallmar thought them contained); quest 10002, 10003 descriptions (blood elf woman, Firewing Point; Lisaile Fireweaver); quest 10012, 10013 (Fel Orc Plans: delicate writing, serve the blood elves, keep us occupied); quest 10007 reward text; quest 10008 description and reward text (keep it from Thrallmar; some stories are best left where they happened)'),
(351937, 3, 3519, 3, 0, 0, 'The Shadow Council at Grangol''var', 'A shadowy band had moved into the ruins of Grangol''var Village, and the scouts who spotted it, Private Weeks for the Alliance and Scout Neftis for the Horde, waited more than a week for anyone to answer their reports. When help finally arrived, each scout handed over a flimsy disguise and sent the newcomer in to mingle. An initiate complained that the interruption meant starting his work over, a laborer grumbled about his pay, and a haughty advisor threatened to have the stranger beaten, but between them the truth came out: these were the Shadow Council. The scouts were aghast. Back went the intruders, weapons drawn, to cut down executioners and summoners and their leader, Shadowmaster Grieve, who had promised his enemies burial in the labyrinth of Auchindoun or sacrifice to Murmur. Lieutenant Gravelhammer and Advisor Faila agreed that a Shadow Council stronghold on their doorstep was the last thing either garrison needed.', 'quest 10038, 10039 descriptions and reward texts (shadowy band; report over a week old); quest 10040, 10041 (disguise; initiate, laborer, advisor); npc_text 9502, 9497, 9505, 9524; quest 10042, 10043 descriptions and reward texts (Shadow Council; Grieve; last thing on our doorstep)'),
(351938, 3, 3519, 4, 2, 0, 'The Wolf Spirit', 'Malukaz of Stonebreaker Hold came to Terokkar through Nagrand, and found to his joy that not all of his people''s old ways were lost. Generations ago, he says, when orc clans still called this forest home, the wolf spirit had a place in their lives. When the orcs departed they left it behind, and in time it grew lonely and left the forest too. Malukaz meant to call it home. For his ritual vestments he needed the pelts of the forest''s timber worgs, and for the final piece the pelt of Ironjaw, the old and cunning patriarch of the wolves who roams the northeast. With incense made in the days of the clans burning by the runestone in his hut, he called to the spirit: his people had given themselves to evil and forgotten it, but now they had returned to honor it again. The wolf spirit answered, and Malukaz declared that Thrall would be proud. Perhaps, he mused, the spirit had been waiting all along for the orcs to see what their choices had wrought.', 'npc_text 9489 (came through Nagrand; culture not lost); quest 10018 description (orc clans once called Terokkar home; spirit left behind, grew lonely); quest 10023 description (Ironjaw patriarch, northeastern region); quest 10791 description and reward text (incense from the days of the clans; runestone; waiting for the orcs to realize); creature_text 18384 (the ceremony; Thrall would be proud)'),
(351939, 3, 3519, 5, 0, 0, 'The Eyes of Skettis', 'Weary of arakkoa raids, Rokag of Stonebreaker Hold sent a messenger to Shattrath to demand the surrender of Rilak the Redeemed, leader of the arakkoa there; Lady Dena Kennedy of the Allerian Stronghold sent hers to learn their secrets instead. Rilak welcomed the curious and told the angry he could do little: some arakkoa had been touched by the naaru and were forever changed, but those in the wild remained as they had always been. He asked for the Eyes of Skettis, orbs through which Terokk watches Veil Reskk and Veil Shienor, and what they showed sent a missive south to Kirrik the Awakened at the refugee caravan. Kirrik began a campaign against Terokk''s colonies: the Darkstone of Veil Skith, which could not be purified, the vengeful spirits of Veil Rhaze, the cursed eggs of Veil Lithic and the signal fires of Veil Shalas. Such blows could not go unanswered. Skettis struck back at Shattrath itself, and its attackers were held off only by those who answered the call to defend the city.', 'quest 10862, 10863 descriptions and reward texts (Rokag''s demand; Lady Dena Kennedy; touched by the naaru); quest 10847 description and reward text (Eyes of Skettis; Terokk''s gaze on the south); quest 10849 (missive to Kirrik); quests 10839, 10848, 10861, 10874 (the four veils); quest 10889, 10879 (Terokk''s revenge; Skettis attacks Shattrath); quest_template_addon 10862, 10863, 10908 (NextQuestID 10847, ExclusiveGroup 10862); quest 10908 description (Kirrik sends travelers to Rilak)'),
(351940, 3, 3519, 6, 0, 0, 'The Book of the Dead', 'Outside the Auchenai Crypts a draenei child, Ha''lei, sees the dead all around him, and only the outcast death priest Ramdor believes him, because Ramdor sees them too. Wanting the spirits to leave him be, Ramdor promised treasure to anyone who would fetch the book of the dead from Ezekiel, an Aldor of Shattrath. Ezekiel had lied; the book had been stolen. Ruffians of the Lower City admitted selling it to two draenei, the younger of whom kept talking of his master''s grand design. The trail led to Nitrin the Learned in Nagrand, and back again to his son Levixus, who now stood atop the ruins of Auchindoun, calling the dead by name and binding them to his will. Nitrin''s tincture, the initiation rite of Auchindoun''s death priests, opened the stranger''s eyes to the world of the dead forever. Levixus fell, and the book went to Ramdor, who confessed he had never known of any treasure. Pointing to the spirits now visible all around, he welcomed his visitor to the fold.', 'quest 10227 description (Ha''lei sees dead draenei; Ramdor sees them too); quest 10228 description (book of the dead held by the Aldor Ezekiel; treasure); quest 10231 description (book stolen; ruffians); quest 10251 description (sold to two draenei; master''s grand design; Abandoned Armory); quest 10252 description and reward text (Levixus binding souls; tincture is the death priests'' initiation; see the dead forever); quest 10253 description and reward text (destroy Levixus; Ramdor lied; welcome to the fold); nagrand.json 351821 (Nitrin)'),
(351941, 3, 3519, 7, 0, 0, 'Refugees of the Bone Wastes', 'The refugee caravan out of the Lower City had stopped in the northern Bone Wastes when Shadow Council cultists fell on it. Its guards believe the danger has passed. The Broken refugee Mekeda does not, and asked for the cultists gathered at Auchindoun''s northern entrance to be driven off before they returned to slit throats in the dark. All Broken were once draenei, Mekeda says, and the spirits of the ancestors dwell in Auchindoun. Orders taken from the cabal, written in a simple shadow cypher learned among the outcasts of the Lower City, revealed that part of the Shadow Council was fleeing the necropolis and hiding powerful artifacts in the Shadow Tomb to the west. Among them were the relics of three patriarchs, Arunen, K''alen and Atalor, which Mekeda would not allow to serve dark ends. A captive of the cultists, Mekeda''s friend Akuno, was brought back to the caravan alive. The Light might have forgotten Mekeda, the refugee says, but Mekeda has not forgotten the Light.', 'quest 10878 description and reward text (cabal attack, scouts to Shattrath, Auchindoun''s northern entrance); npc_text 10662 (all Broken were once draenei; ancestors'' spirits in Auchindoun); quest 10880 reward text (shadow cypher; outcasts and refugees in the Lower City); quest 10881 description and reward text (Shadow Council fleeing; Shadow Tomb; Arunen, K''alen, Atalor; the Light might have forgotten me); quest 10887 and creature_text 22377 (Akuno, friend of Mekeda); quest 10029 description (caravan stopping in the northern Bone Wastes); creature_model_info 20962 (male)'),
(351942, 3, 3519, 8, 0, 0, 'The Fallen Exarch', 'In the Bone Wastes the vindicators of the Sha''tar under Commander Ra''vaj have battled the Auchenai for days on the grounds east of their camp, with no end in sight. Worse than the losses is what follows them. Every body that falls, Auchenai or Sha''tar, is snatched from the field and its soul lifted away. Ra''vaj would not let the fiends feed their rituals on his dead. With proper burial out of the question, he handed out torches to burn every corpse on the field, though he knew it was not enough. A hero was needed. Strikes on the Auchenai initiates and doomsayers kept them busy while his scouts slipped behind their lines, and what the scouts found was worse still: the Auchenai had dragged a coffin out of the Auchenai Crypts and were feeding it stolen souls, and the scouts believed it held the first exarch of the crypts, whom the Auchenai meant to raise. The coffin''s contents were destroyed before they could be revived, setting the Auchenai back by weeks.', 'quest 10913 description and reward text (days of battle; souls lifted; burn every corpse; not enough); quest 10914 description (a hero is needed; scouts behind their lines); quest 10915 description and reward text (coffin from the Auchenai Crypts; first exarch; set back several weeks); gameobject 184999 Auchenai Coffin position; areatrigger 4404 Auchenai Crypts entrance on the west'),
(351943, 3, 3519, 9, 0, 0, 'The Skyguard over Skettis', 'The Sha''tari Skyguard welcomes recruits who can fly, but first it wants to see whether they can fight. Those who prove themselves in Shattrath are sent on with a package of explosives to Sky Sergeant Doryn at Blackwind Landing, the camp outside Skettis. There the work begins at once. The arakkoa are breeding monstrous kaliri to use against the Skyguard''s scouts, and recruits must blast the hatcheries atop the city''s dwellings while dodging the great birds that guard them. Scouts shot down over the city must be led out on foot, and the hungry nether rays taken to the woods to hunt warp chasers. All the while the wounded Sky Commander Adaris raved that the true masters of Skettis were hidden from sight. His healer Severin humored him with an elixir brewed from arakkoa shadow dust, and it revealed a world of shadows where the three talonpriests of Skettis, Ishaal, Skizzik and Zellek, had hidden all along. In Veil Ala''rak, near Blackwind Lake, the talonpriests were found and slain.', 'quest 11096 description (can you fight; Gordunni of the Barrier Hills); quest 11098 description (explosives to Doryn at Blackwind Landing); quest 11008 description (kaliri hatcheries); quest 11085 (Skyguard Prisoner); quest 11093 (hungry nether rays, warp chasers); quest 11004, 11005 descriptions (Adaris''s world of shadows; talonpriests Ishaal, Skizzik, Zellek in Veil Ala''rak)'),
(351944, 3, 3519, 10, 0, 0, 'The Return of Terokk', 'Talonpriest Ishaal carried an almanac of celestial charts in an ancient arakkoa script, and the failing Adaris sent it to Rilak the Redeemed in Shattrath. Rilak read in it the coming return of Terokk, the most terrible king in arakkoa history, and saw only one chance: to bring him into the world before he regained his full strength. Adaris would not hear of it. But Hazzik, his caged arakkoa prisoner, born to the lowest caste that Terokk''s talonpriests once sacrificed, quietly offered a bargain. In one of the shabby disguises he used to make for ethereal book smugglers, a stranger fooled the nearly blind scribe Sahaak at Terokk''s Rest into handing over the Adversarial Bloodlines, which named the descendants of Terokk''s ancient enemies, held captive by the talonpriests. Prophecy said their deaths would herald his return. Gezzarak the Huntress, the crystal giant Karrog, the heretic Darkscreecher Akkarai and Vakkiz the Windrager were summoned and slain. At last Adaris relented and sent his riders. Called to Terokk''s Rest before the stars aligned, Terokk fell.', 'quest 11021 description (Ishaal''s almanac, ancient arakkoa script, charts of celestial bodies); quest 11024, 11028 descriptions and reward text (Rilak: most terrible king; bring him prematurely; Adaris: purely military matter); quest 11056 description (Hazzik: lowest caste, sacrificed; Adaris would not approve); quest 11029 description and reward text (shabby disguise for ethereal smugglers; Sahaak; descendants of Terokk''s ancient enemies; prophecy); quest 11885 description (Gezzarak, Karrog, Akkarai, Vakkiz); quest 11073 description and creature_text 21838, 23377 (summoning; stars not aligned; Skyguard support)');
